require __DIR__.'/config/db.php'; require __DIR__.'/config/security.php';
$stmt=$pdo->query("SELECT * FROM contenus WHERE publie=1 ORDER BY created_at DESC"); $items=$stmt->fetchAll();
function youtube_embed(?string $url): string { $url=trim($url ?? ''); if (preg_match('~(?:youtu\.be/|youtube\.com/(?:watch\?v=|embed/|shorts/))([A-Za-z0-9_-]{11})~',$url,$m)) return 'https://www.youtube-nocookie.com/embed/'.$m[1]; return ''; }
?>
